      bit_clock => hs_bit_clock,
      dphy0_hs_clk(1 downto 0) => dphy0_hs_clk(1 downto 0),
      dphy0_hs_d0(1 downto 0) => dphy0_hs_d0(1 downto 0),
      dphy0_hs_d1(1 downto 0) => dphy0_hs_d1(1 downto 0),
      dphy0_hs_d2(1 downto 0) => dphy0_hs_d2(1 downto 0),
      dphy0_hs_d3(1 downto 0) => dphy0_hs_d3(1 downto 0),
      dphy0_lp_d0_OBUF(1 downto 0) => dphy0_lp_d0_OBUF(1 downto 0),
      \dphy0_lp_d0_TRI[0]\ => \dphy0_lp_d0_TRI[0]\,
