      dphy1_hs_d2(1 downto 0) => dphy1_hs_d2(1 downto 0),
      dphy1_hs_d3(1 downto 0) => dphy1_hs_d3(1 downto 0),
      dphy1_lp_d0_OBUF(1 downto 0) => dphy1_lp_d0_OBUF(1 downto 0),
      \dphy1_lp_d0_TRI[0]\ => \dphy1_lp_d0_TRI[0]\,
