patgen: entity work.test_pattern_enhanced
     port map (
      AR(0) => reset,
      D(1 downto 0) => switches_IBUF(1 downto 0),
      left_video_den => left_video_den,
      pattern_hsync => pattern_hsync,
      pattern_vsync => pattern_vsync,
      pixel_clock => pixel_clock,
      reset_n_IBUF => reset_n_IBUF,
      \rgb_int_reg[23]\(23 downto 16) => pattern_rgb(7 downto 0),
      \rgb_int_reg[23]\(15 downto 8) => pattern_rgb(15 downto 8),
      \rgb_int_reg[23]\(7 downto 0) => pattern_rgb(23 downto 16),
      right_video_den => right_video_den,
      rst => \right_dsi/video_cmd_ctrl/fifo_rst\,
      word_pack_reset => \left_dsi/video_cmd_ctrl/word_pack_reset\,
      word_pack_reset_0 => \right_dsi/video_cmd_ctrl/word_pack_reset\
    );
reset_n_IBUF_inst: unisim.vcomponents.IBUF
     port map (
      I => reset_n,
      O => reset_n_IBUF
    );
\switches_IBUF[0]_inst\: unisim.vcomponents.IBUF
     port map (
      I => switches(0),
