te_toggle_i_1: unisim.vcomponents.LUT1
    generic map(
      INIT => X"1"
    )
        port map (
      I0 => leds_OBUF(2),
      O => te_toggle_i_1_n_0
    );
te_toggle_reg: unisim.vcomponents.FDRE
    generic map(
      INIT => '0'
    )
        port map (
      C => lcd_te_IBUF_BUFG,
      CE => '1',
      D => te_toggle_i_1_n_0,
      Q => leds_OBUF(2),
      R => '0'
    );
vdda_en_OBUF_inst: unisim.vcomponents.OBUF
     port map (
